# -*- coding: utf-8 -*-
r"""
CÀI ĐẶT V9.2 - CHỨC NĂNG SÁP NHẬP TRƯỜNG DÙNG CHUNG TRONG PHẦN MỀM
=====================================================================

- Không sửa database khi cài đặt.
- Tự backup các file mã nguồn bị thay đổi.
- Nếu cài đặt lỗi, tự khôi phục mã nguồn cũ.
- Thêm menu: 1.3.2. Sáp nhập trường.
- Chỉ ADMIN/SO được truy cập.
- Trang sáp nhập có Xem trước + mô phỏng RAM + backup DB + transaction + rollback.
- Backup trước sáp nhập được tích hợp vào trang Khôi phục database hiện có.

Chạy:
    cd C:\PhoCap
    .\.venv\Scripts\python.exe .\cai_dat_chuc_nang_sap_nhap_truong_dung_chung_v9_2.py
"""

from __future__ import annotations

import ast
import base64
import shutil
import sys
import zipfile
from datetime import datetime
from pathlib import Path

ROOT = Path(r"C:\PhoCap")

PAYLOADS = {
    Path("app/services/school_merger_service.py"): "",
    Path("app/routers/school_merger.py"): "",
    Path("app/templates/data_tools/school_merger.html"): "",
}

PATCH_FILES = [
    Path("app/main.py"),
    Path("app/access_control.py"),
    Path("app/routers/data_tools.py"),
    Path("app/templates/partials/dropdown_menu_v1.html"),
]


def fail(message: str) -> None:
    raise RuntimeError(message)


def read_text(rel: Path) -> str:
    path = ROOT / rel
    if not path.is_file():
        fail(f"Không tìm thấy file bắt buộc: {path}")
    return path.read_text(encoding="utf-8")


def write_text(rel: Path, text: str) -> None:
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def patch_once(text: str, marker: str, anchor: str, replacement: str, label: str) -> str:
    if marker in text:
        return text
    if anchor not in text:
        fail(f"Không tìm thấy điểm chèn {label}. Dừng an toàn, chưa sửa tiếp.")
    return text.replace(anchor, replacement, 1)


def backup_sources(backup_dir: Path) -> dict[Path, bool]:
    existed: dict[Path, bool] = {}
    for rel in PATCH_FILES + list(PAYLOADS.keys()):
        src = ROOT / rel
        existed[rel] = src.exists()
        if src.exists():
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    return existed


def restore_sources(backup_dir: Path, existed: dict[Path, bool]) -> None:
    for rel, was_present in existed.items():
        target = ROOT / rel
        saved = backup_dir / rel
        try:
            if was_present and saved.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(saved, target)
            elif not was_present and target.exists():
                target.unlink()
        except Exception as exc:
            print(f"CẢNH BÁO: không khôi phục được {target}: {exc}")


def syntax_check(rel: Path) -> None:
    ast.parse(read_text(rel), filename=str(ROOT / rel))


def main() -> None:
    if not ROOT.is_dir():
        fail(f"Không tìm thấy dự án: {ROOT}")

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = ROOT / f"backup_ma_nguon_truoc_sap_nhap_v9_2_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)

    db_path = ROOT / "data" / "phocap.db"
    db_before = None
    if db_path.exists():
        st = db_path.stat()
        db_before = (st.st_size, st.st_mtime_ns)

    existed = backup_sources(backup_dir)
    modified: list[str] = []

    try:
        for rel, encoded in PAYLOADS.items():
            data = base64.b64decode(encoded.encode("ascii"))
            path = ROOT / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
            modified.append(str(rel))

        # main.py: import router.
        rel = Path("app/main.py")
        text = read_text(rel)
        anchor = "from app.routers.data_tools import router as data_tools_router\n"
        replacement = anchor + (
            "# === SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_IMPORT ===\n"
            "from app.routers.school_merger import router as school_merger_router\n"
        )
        text = patch_once(text, "SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_IMPORT", anchor, replacement, "import router sáp nhập")
        anchor = "app.include_router(data_tools_router)\n"
        replacement = anchor + (
            "# === SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_INCLUDE ===\n"
            "app.include_router(school_merger_router)\n"
        )
        text = patch_once(text, "SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_INCLUDE", anchor, replacement, "include router sáp nhập")
        write_text(rel, text)
        modified.append(str(rel))

        # AccessControl: chỉ ADMIN/SO cho toàn bộ Công cụ dữ liệu.
        rel = Path("app/access_control.py")
        text = read_text(rel)
        anchor = "ROLE_RULES = (\n"
        replacement = anchor + (
            "    # === SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_ACCESS ===\n"
            "    (\"/cong-cu-du-lieu\", ADMIN_ROLE_CODES),\n"
        )
        text = patch_once(text, "SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_ACCESS", anchor, replacement, "phân quyền Công cụ dữ liệu")
        write_text(rel, text)
        modified.append(str(rel))

        # Cho backup trước sáp nhập xuất hiện trong trang Khôi phục database.
        rel = Path("app/routers/data_tools.py")
        text = read_text(rel)
        anchor = 'RESTORE_BACKUP_PREFIXES = (\n    "backup_thu_cong_",\n'
        replacement = (
            'RESTORE_BACKUP_PREFIXES = (\n'
            '    "backup_thu_cong_",\n'
            '    # === SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_BACKUP_PREFIX ===\n'
            '    "backup_truoc_sap_nhap_",\n'
        )
        text = patch_once(text, "SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_BACKUP_PREFIX", anchor, replacement, "prefix backup sáp nhập")
        anchor = (
            'def _restore_backup_type(name: str) -> str:\n'
            '    if name.startswith("backup_thu_cong_"):\n'
            '        return "Backup thủ công"\n'
        )
        replacement = anchor + (
            '    # === SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_BACKUP_TYPE ===\n'
            '    if name.startswith("backup_truoc_sap_nhap_"):\n'
            '        return "Backup trước khi sáp nhập trường"\n'
        )
        text = patch_once(text, "SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_BACKUP_TYPE", anchor, replacement, "nhãn backup sáp nhập")
        write_text(rel, text)
        modified.append(str(rel))

        # Menu 1.3.2.
        rel = Path("app/templates/partials/dropdown_menu_v1.html")
        text = read_text(rel)
        anchor = (
            '                            <a\n'
            '                                href="/cong-cu-du-lieu/don-du-lieu-dieu-tra"\n'
            '                                role="menuitem"\n'
            '                            >\n'
            '                                1.3.1. Dọn dẹp dữ liệu điều tra\n'
            '                            </a>\n'
        )
        replacement = anchor + (
            '                            {# === SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_MENU === #}\n'
            '                            <a\n'
            '                                href="/cong-cu-du-lieu/sap-nhap-truong"\n'
            '                                role="menuitem"\n'
            '                            >\n'
            '                                1.3.2. Sáp nhập trường\n'
            '                            </a>\n'
        )
        text = patch_once(text, "SAP_NHAP_TRUONG_DUNG_CHUNG_V9_2_MENU", anchor, replacement, "menu 1.3.2")

        # Đánh dấu nhóm Danh mục active khi đang ở Công cụ dữ liệu.
        old_active = "menu_path.startswith('/lop-hoc') %}is-active{% endif %}"
        new_active = "menu_path.startswith('/lop-hoc') or menu_path.startswith('/cong-cu-du-lieu') %}is-active{% endif %}"
        if old_active in text and new_active not in text:
            text = text.replace(old_active, new_active, 1)
        write_text(rel, text)
        modified.append(str(rel))

        # Kiểm tra cú pháp Python.
        for rel in (
            Path("app/main.py"),
            Path("app/access_control.py"),
            Path("app/routers/data_tools.py"),
            Path("app/routers/school_merger.py"),
            Path("app/services/school_merger_service.py"),
        ):
            syntax_check(rel)

        menu_text = read_text(Path("app/templates/partials/dropdown_menu_v1.html"))
        if '/cong-cu-du-lieu/sap-nhap-truong' not in menu_text:
            fail("Menu sáp nhập chưa được cài thành công.")
        if not (ROOT / "app/templates/data_tools/school_merger.html").is_file():
            fail("Thiếu template school_merger.html.")
        if "school_merger_router" not in read_text(Path("app/main.py")):
            fail("Router sáp nhập chưa được đăng ký trong main.py.")

        # Xác nhận installer không sửa database.
        db_after = None
        if db_path.exists():
            st = db_path.stat()
            db_after = (st.st_size, st.st_mtime_ns)
        database_unchanged = db_before == db_after
        if db_before is not None and not database_unchanged:
            fail("Database thay đổi trong lúc cài mã nguồn; dừng và khôi phục mã nguồn.")

        report_dir = ROOT / f"ket_qua_cai_dat_sap_nhap_v9_2_{stamp}"
        report_dir.mkdir(parents=True, exist_ok=False)
        report = (
            "CÀI ĐẶT CHỨC NĂNG SÁP NHẬP TRƯỜNG DÙNG CHUNG V9.2\n"
            + "=" * 90 + "\n"
            + "STATUS = SUCCESS\n"
            + f"Backup mã nguồn: {backup_dir}\n"
            + f"Database không thay đổi: {'YES' if database_unchanged else 'NO'}\n"
            + "\nFILE ĐÃ CÀI/SỬA:\n- " + "\n- ".join(modified)
            + "\n\nROUTE: /cong-cu-du-lieu/sap-nhap-truong\n"
            + "MENU: 1. Danh mục -> 1.3. Công cụ dữ liệu -> 1.3.2. Sáp nhập trường\n"
            + "QUYỀN: ADMIN/SO\n"
            + "\nCài đặt chỉ thay mã nguồn, chưa thực hiện bất kỳ lần sáp nhập database nào.\n"
        )
        (report_dir / "00_KET_QUA_CAI_DAT_V9_2.txt").write_text(report, encoding="utf-8")

        zip_path = ROOT / f"ket_qua_cai_dat_sap_nhap_v9_2_{stamp}.zip"
        with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            for p in report_dir.iterdir():
                zf.write(p, arcname=p.name)

        print("=" * 100)
        print("CÀI ĐẶT V9.2 THÀNH CÔNG")
        print("=" * 100)
        print(f"Backup mã nguồn: {backup_dir}")
        print("Database: KHÔNG THAY ĐỔI")
        print("Menu mới: 1.3.2. Sáp nhập trường")
        print("Route: /cong-cu-du-lieu/sap-nhap-truong")
        print(f"ZIP kết quả: {zip_path}")
        print()
        print("BƯỚC TIẾP: khởi động lại Uvicorn, đăng nhập tài khoản Sở/Admin và mở menu 1.3.2.")

    except Exception as exc:
        print()
        print("=" * 100)
        print("CÀI ĐẶT V9.2 THẤT BẠI - ĐANG KHÔI PHỤC MÃ NGUỒN")
        print("=" * 100)
        print(repr(exc))
        restore_sources(backup_dir, existed)
        print(f"Đã khôi phục từ: {backup_dir}")
        print("Database không được installer chủ động sửa.")
        sys.exit(2)


if __name__ == "__main__":
    main()
